action_details.action_postfix:
0.0 /result.mi_deduction xdef
result.deduction_used "itemized" streq {
  result.total_itemized /result.mi_deduction xdef
} if
job.taxpayers {
  taxpayer.age 67 >= {
    job.filing_status MFJ streq job.filing_status QSS streq or {
      mi_standard_deduction_mfj_67 result.mi_deduction fmax /result.mi_deduction xdef
    } {
      mi_standard_deduction_single_67 result.mi_deduction fmax /result.mi_deduction xdef
    } ifelse
  } if
} forall
mi_personal_exemption job.taxpayers length i* /result.mi_exemptions xdef
0.0 /result.mi_retirement_subtraction xdef
job.taxpayers {
  taxpayer.retirement_income 0.0 f> {
    job.filing_status MFJ streq job.filing_status QSS streq or {
      mi_retirement_tier1_limit_mfj /mi_limit xdef
    } {
      mi_retirement_tier1_limit /mi_limit xdef
    } ifelse
    taxpayer.retirement_income mi_limit fmin result.mi_retirement_subtraction f+ /result.mi_retirement_subtraction xdef
  } if
} forall
result.agi result.mi_deduction f- result.mi_exemptions f- result.mi_retirement_subtraction f- 0 fmax /result.mi_taxable_income xdef
result.mi_taxable_income mi_tax_rate f* /result.mi_state_tax xdef
"  Michigan AGI (same as Federal AGI): $" result.agi cvs strconcat job.audit_trail swap addto
"  Michigan Deduction: $" result.mi_deduction cvs strconcat job.audit_trail swap addto
"  Michigan Personal Exemptions: $" result.mi_exemptions cvs strconcat job.audit_trail swap addto
"  Michigan Retirement Subtraction: $" result.mi_retirement_subtraction cvs strconcat job.audit_trail swap addto
"  Michigan Taxable Income: $" result.mi_taxable_income cvs strconcat job.audit_trail swap addto
"  MI Tax (4.25% on $" result.mi_taxable_income cvs strconcat "): $" strconcat result.mi_state_tax cvs strconcat job.audit_trail swap addto
